<div class="page-heading"><div><a class="back-link" href="<?= site_url('petugas/master') ?>">← Master data</a><div class="eyebrow">Pemeriksaan</div><h1>Master kaji ulang</h1><p>Atur uraian pemeriksaan yang wajib dinilai pada setiap permohonan.</p></div><button class="button primary" type="button" data-modal-open="check-0">+ Tambah rincian</button></div>
<section class="card table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Urutan</th><th>Uraian</th><th>Keterangan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= (int)$row->sort_order ?></td><td><strong><?= e($row->label) ?></strong></td><td><?= e($row->description ?: '—') ?></td><td><span class="badge <?= $row->is_active?'success':'danger' ?>"><?= $row->is_active?'Aktif':'Nonaktif' ?></span></td><td><div class="row-actions"><button class="action-link" type="button" data-modal-open="check-<?= (int)$row->id ?>">Edit</button><form method="post" action="<?= site_url('petugas/master/verifikasi/status/'.$row->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link" type="submit"><?= $row->is_active?'Nonaktifkan':'Aktifkan' ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php foreach (array_merge(array(NULL),$rows) as $row): $id=$row?(int)$row->id:0; ?><dialog class="admin-modal" id="check-<?= $id ?>"><div class="modal-head"><h2><?= $row?'Edit':'Tambah' ?> rincian verifikasi</h2><button type="button" data-modal-close class="modal-close" aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/master/verifikasi/simpan'.($id?'/'.$id:'')) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><label>Uraian pemeriksaan<input name="label" required minlength="3" maxlength="190" value="<?= e($row?$row->label:'') ?>"></label><label>Keterangan<textarea name="description" maxlength="500" rows="3"><?= e($row?$row->description:'') ?></textarea></label><label>Urutan<input type="number" name="sort_order" min="0" max="9999" value="<?= $row?(int)$row->sort_order:100 ?>"></label></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Simpan</button></div></form></dialog><?php endforeach; ?>
